/* calc: evaluate one signed 64-bit integer expression per line of stdin.
 *
 * The grammar is evaluated with an explicit operator-precedence (shunting-yard)
 * machine rather than recursive descent, so arbitrarily deep nesting such as
 * "((((...))))" or "------1" cannot exhaust the call stack. */
#include "commands.h"
#include "io.h"

#include <stdbool.h>
#include <stdlib.h>
#include <string.h>

enum { OP_NEG = 'n', OP_PAREN = '(' };

typedef struct {
    void *data;
    size_t len;
    size_t cap;
} Stack;

static void stack_reserve(Stack *s, size_t elem)
{
    if (s->len == s->cap) {
        s->cap = s->cap ? s->cap * 2 : 64;
        s->data = xrealloc(s->data, s->cap * elem);
    }
}

typedef struct {
    Stack vals; /* int64_t */
    Stack ops;  /* char: binary operator, OP_NEG or OP_PAREN */
} Machine;

static void push_val(Machine *m, int64_t v)
{
    stack_reserve(&m->vals, sizeof v);
    ((int64_t *)m->vals.data)[m->vals.len++] = v;
}

static void push_op(Machine *m, char op)
{
    stack_reserve(&m->ops, 1);
    ((char *)m->ops.data)[m->ops.len++] = op;
}

static char top_op(const Machine *m)
{
    return m->ops.len ? ((const char *)m->ops.data)[m->ops.len - 1] : '\0';
}

static int precedence(char op)
{
    switch (op) {
    case OP_NEG:
        return 3;
    case '*':
    case '/':
    case '%':
        return 2;
    case '+':
    case '-':
        return 1;
    default:
        return 0; /* OP_PAREN and none: never reduced by an operator */
    }
}

/* Compute a op b exactly; false on overflow or division by zero. */
static bool apply_binary(char op, int64_t a, int64_t b, int64_t *r)
{
    switch (op) {
    case '+':
        if ((b > 0 && a > INT64_MAX - b) || (b < 0 && a < INT64_MIN - b))
            return false;
        *r = a + b;
        return true;
    case '-':
        if ((b < 0 && a > INT64_MAX + b) || (b > 0 && a < INT64_MIN + b))
            return false;
        *r = a - b;
        return true;
    case '*':
        if (a == 0 || b == 0) {
            *r = 0;
            return true;
        }
        if (a > 0 ? (b > 0 ? a > INT64_MAX / b : b < INT64_MIN / a)
                  : (b > 0 ? a < INT64_MIN / b : b < INT64_MAX / a))
            return false;
        *r = a * b;
        return true;
    case '/':
        if (b == 0 || (a == INT64_MIN && b == -1))
            return false;
        *r = a / b;
        return true;
    case '%':
        if (b == 0)
            return false;
        *r = b == -1 ? 0 : a % b; /* INT64_MIN % -1 is 0, but UB in C */
        return true;
    default:
        return false;
    }
}

/* Pop and apply the top operator. */
static bool reduce(Machine *m)
{
    char op = ((char *)m->ops.data)[--m->ops.len];
    int64_t *v = m->vals.data;
    if (op == OP_NEG) {
        int64_t *x = &v[m->vals.len - 1];
        if (*x == INT64_MIN)
            return false;
        *x = -*x;
        return true;
    }
    int64_t b = v[--m->vals.len];
    int64_t *a = &v[m->vals.len - 1];
    return apply_binary(op, *a, b, a);
}

/* Apply stacked operators that bind at least as tightly as prec. */
static bool reduce_while(Machine *m, int prec)
{
    while (m->ops.len && precedence(top_op(m)) >= prec && top_op(m) != OP_PAREN) {
        if (!reduce(m))
            return false;
    }
    return true;
}

static inline bool is_blank(char c)
{
    return c == ' ' || c == '\t';
}

static inline bool is_digit(char c)
{
    return c >= '0' && c <= '9';
}

/* Evaluate the expression in [p, end). */
static bool evaluate(Machine *m, const char *p, const char *end, int64_t *result)
{
    m->vals.len = 0;
    m->ops.len = 0;
    bool want_operand = true;

    for (;;) {
        while (p < end && is_blank(*p))
            p++;
        if (p == end)
            break;
        char c = *p;

        if (want_operand) {
            if (is_digit(c)) {
                int64_t v = 0;
                for (; p < end && is_digit(*p); p++) {
                    int d = *p - '0';
                    if (v > (INT64_MAX - d) / 10)
                        return false; /* literal out of range */
                    v = v * 10 + d;
                }
                push_val(m, v);
                want_operand = false;
                continue;
            }
            if (c == '-')
                push_op(m, OP_NEG);
            else if (c == '(')
                push_op(m, OP_PAREN);
            else
                return false;
            p++;
            continue;
        }

        switch (c) {
        case '+':
        case '-':
        case '*':
        case '/':
        case '%':
            if (!reduce_while(m, precedence(c)))
                return false;
            push_op(m, c);
            want_operand = true;
            break;
        case ')':
            if (!reduce_while(m, 1))
                return false;
            if (top_op(m) != OP_PAREN)
                return false; /* unmatched ')' */
            m->ops.len--;
            break;
        default:
            return false;
        }
        p++;
    }

    if (want_operand)
        return false; /* empty input or dangling operator */
    if (!reduce_while(m, 1) || m->ops.len)
        return false; /* arithmetic error or unmatched '(' */
    *result = ((int64_t *)m->vals.data)[0];
    return true;
}

int cmd_calc(void)
{
    Input in = input_read_all(stdin);
    const char *p = in.data;
    const char *end = in.data + in.len;
    Machine m = { 0 };
    Output out;
    out_init(&out, stdout);

    while (p < end) {
        const char *nl = memchr(p, '\n', (size_t)(end - p));
        const char *e = nl ? nl : end;

        const char *q = p;
        while (q < e && is_blank(*q))
            q++;
        if (q < e) {
            int64_t v;
            if (evaluate(&m, q, e, &v))
                out_i64(&out, v);
            else
                out_write(&out, "error", 5);
            out_char(&out, '\n');
        }
        p = nl ? nl + 1 : end;
    }

    out_finish(&out);
    free(m.vals.data);
    free(m.ops.data);
    input_free(&in);
    return EXIT_SUCCESS;
}

#ifndef SUITE_COMMANDS_H
#define SUITE_COMMANDS_H

/* Each subcommand reads stdin, writes stdout, and returns an exit status. */
int cmd_wordfreq(void);
int cmd_lru(void);
int cmd_calc(void);

#endif

#ifndef SUITE_HASH_H
#define SUITE_HASH_H

#include <stddef.h>
#include <stdint.h>

/* 64-bit FNV-1a with a final avalanche mix, suitable for power-of-two tables. */
static inline uint64_t hash_bytes(const char *s, size_t n)
{
    uint64_t h = 0xcbf29ce484222325u;
    for (size_t i = 0; i < n; i++) {
        h ^= (unsigned char)s[i];
        h *= 0x100000001b3u;
    }
    h ^= h >> 33;
    h *= 0xff51afd7ed558ccdu;
    h ^= h >> 33;
    return h;
}

#endif

#include "io.h"

#include <stdlib.h>
#include <string.h>

static void die(const char *what)
{
    perror(what);
    exit(EXIT_FAILURE);
}

void *xmalloc(size_t n)
{
    void *p = malloc(n ? n : 1);
    if (!p)
        die("malloc");
    return p;
}

void *xcalloc(size_t count, size_t size)
{
    void *p = calloc(count ? count : 1, size ? size : 1);
    if (!p)
        die("calloc");
    return p;
}

void *xrealloc(void *p, size_t n)
{
    void *q = realloc(p, n ? n : 1);
    if (!q)
        die("realloc");
    return q;
}

Input input_read_all(FILE *stream)
{
    size_t cap = 1 << 16;
    size_t len = 0;
    char *data = xmalloc(cap);

    for (;;) {
        if (cap - len < 2) {
            cap *= 2;
            data = xrealloc(data, cap);
        }
        size_t got = fread(data + len, 1, cap - len - 1, stream);
        len += got;
        if (got == 0) {
            if (ferror(stream))
                die("read");
            break;
        }
    }
    data[len] = '\0';
    return (Input){ .data = data, .len = len };
}

void input_free(Input *in)
{
    free(in->data);
    in->data = NULL;
    in->len = 0;
}

enum { OUT_CAP = 1 << 16 };

void out_init(Output *out, FILE *stream)
{
    out->stream = stream;
    out->buf = xmalloc(OUT_CAP);
    out->len = 0;
    out->cap = OUT_CAP;
}

static void out_drain(Output *out)
{
    if (out->len && fwrite(out->buf, 1, out->len, out->stream) != out->len)
        die("write");
    out->len = 0;
}

void out_write(Output *out, const char *s, size_t n)
{
    if (n > out->cap - out->len) {
        out_drain(out);
        if (n > out->cap) {
            if (fwrite(s, 1, n, out->stream) != n)
                die("write");
            return;
        }
    }
    memcpy(out->buf + out->len, s, n);
    out->len += n;
}

void out_char(Output *out, char c)
{
    if (out->len == out->cap)
        out_drain(out);
    out->buf[out->len++] = c;
}

void out_cstr(Output *out, const char *s)
{
    out_write(out, s, strlen(s));
}

void out_u64(Output *out, uint64_t v)
{
    char tmp[20];
    size_t i = sizeof tmp;
    do {
        tmp[--i] = (char)('0' + v % 10);
        v /= 10;
    } while (v);
    out_write(out, tmp + i, sizeof tmp - i);
}

void out_i64(Output *out, int64_t v)
{
    if (v < 0) {
        out_char(out, '-');
        /* Negate in unsigned arithmetic so INT64_MIN is handled. */
        out_u64(out, (uint64_t)0 - (uint64_t)v);
    } else {
        out_u64(out, (uint64_t)v);
    }
}

void out_finish(Output *out)
{
    out_drain(out);
    if (fflush(out->stream) != 0)
        die("write");
    free(out->buf);
    out->buf = NULL;
}

#ifndef SUITE_IO_H
#define SUITE_IO_H

#include <stddef.h>
#include <stdint.h>
#include <stdio.h>

/* A heap buffer holding an entire input stream. data is NUL-terminated
 * (the terminator is not counted in len) so scanners may use a sentinel. */
typedef struct {
    char *data;
    size_t len;
} Input;

/* Read all of stream into memory. Exits with a diagnostic on failure. */
Input input_read_all(FILE *stream);
void input_free(Input *in);

/* Buffered writer over a FILE*, flushed when full and on out_flush(). */
typedef struct {
    FILE *stream;
    char *buf;
    size_t len;
    size_t cap;
} Output;

void out_init(Output *out, FILE *stream);
void out_write(Output *out, const char *s, size_t n);
void out_char(Output *out, char c);
void out_cstr(Output *out, const char *s);
void out_i64(Output *out, int64_t v);
void out_u64(Output *out, uint64_t v);
/* Flush and release the buffer. */
void out_finish(Output *out);

/* Allocation helpers that abort the program on failure. */
void *xmalloc(size_t n);
void *xcalloc(size_t count, size_t size);
void *xrealloc(void *p, size_t n);

#endif

/* lru: simulate an LRU cache driven by SET/GET/DEL/SIZE commands on stdin. */
#include "commands.h"
#include "hash.h"
#include "io.h"

#include <stdbool.h>
#include <stdlib.h>
#include <string.h>

#define NIL UINT32_MAX

/* Keys and values point into the input buffer, which outlives the cache. */
typedef struct {
    const char *key;
    const char *val;
    uint64_t hash;
    uint32_t klen;
    uint32_t vlen;
    uint32_t prev; /* towards most recently used */
    uint32_t next; /* towards least recently used; free-list link when unused */
} Node;

typedef struct {
    Node *nodes;
    uint32_t nodes_len; /* nodes ever allocated */
    uint32_t nodes_cap;
    uint32_t free_head;

    uint32_t *slots; /* node index or NIL; linear probing, no tombstones */
    size_t mask;

    uint32_t head; /* most recently used */
    uint32_t tail; /* least recently used */
    uint32_t size;
    uint32_t capacity;
} Cache;

static void cache_init(Cache *c, uint32_t capacity)
{
    *c = (Cache){ .free_head = NIL, .head = NIL, .tail = NIL, .capacity = capacity };
    c->nodes_cap = 64;
    c->nodes = xmalloc(c->nodes_cap * sizeof *c->nodes);
    size_t slots = 128;
    c->slots = xmalloc(slots * sizeof *c->slots);
    memset(c->slots, 0xff, slots * sizeof *c->slots);
    c->mask = slots - 1;
}

static void cache_free(Cache *c)
{
    free(c->nodes);
    free(c->slots);
}

/* ---- recency list ---- */

static void list_unlink(Cache *c, uint32_t i)
{
    Node *n = &c->nodes[i];
    if (n->prev != NIL)
        c->nodes[n->prev].next = n->next;
    else
        c->head = n->next;
    if (n->next != NIL)
        c->nodes[n->next].prev = n->prev;
    else
        c->tail = n->prev;
}

static void list_push_front(Cache *c, uint32_t i)
{
    Node *n = &c->nodes[i];
    n->prev = NIL;
    n->next = c->head;
    if (c->head != NIL)
        c->nodes[c->head].prev = i;
    else
        c->tail = i;
    c->head = i;
}

static void list_touch(Cache *c, uint32_t i)
{
    if (c->head != i) {
        list_unlink(c, i);
        list_push_front(c, i);
    }
}

/* ---- hash index ---- */

/* Return the slot holding key, or the empty slot where it would go. */
static size_t index_find(const Cache *c, const char *key, uint32_t klen, uint64_t h)
{
    size_t s = h & c->mask;
    for (;;) {
        uint32_t i = c->slots[s];
        if (i == NIL)
            return s;
        const Node *n = &c->nodes[i];
        if (n->hash == h && n->klen == klen && memcmp(n->key, key, klen) == 0)
            return s;
        s = (s + 1) & c->mask;
    }
}

static void index_grow(Cache *c)
{
    size_t cap = (c->mask + 1) * 2;
    uint32_t *slots = xmalloc(cap * sizeof *slots);
    memset(slots, 0xff, cap * sizeof *slots);
    size_t mask = cap - 1;
    for (size_t s = 0; s <= c->mask; s++) {
        uint32_t i = c->slots[s];
        if (i == NIL)
            continue;
        size_t t = c->nodes[i].hash & mask;
        while (slots[t] != NIL)
            t = (t + 1) & mask;
        slots[t] = i;
    }
    free(c->slots);
    c->slots = slots;
    c->mask = mask;
}

/* Backward-shift deletion keeps probe chains intact without tombstones. */
static void index_remove_slot(Cache *c, size_t hole)
{
    size_t s = hole;
    for (;;) {
        s = (s + 1) & c->mask;
        uint32_t i = c->slots[s];
        if (i == NIL)
            break;
        size_t home = c->nodes[i].hash & c->mask;
        bool stays = hole <= s ? (hole < home && home <= s) : (hole < home || home <= s);
        if (!stays) {
            c->slots[hole] = i;
            hole = s;
        }
    }
    c->slots[hole] = NIL;
}

/* ---- node pool ---- */

static uint32_t node_alloc(Cache *c)
{
    if (c->free_head != NIL) {
        uint32_t i = c->free_head;
        c->free_head = c->nodes[i].next;
        return i;
    }
    if (c->nodes_len == c->nodes_cap) {
        c->nodes_cap *= 2;
        c->nodes = xrealloc(c->nodes, (size_t)c->nodes_cap * sizeof *c->nodes);
    }
    return c->nodes_len++;
}

static void node_release(Cache *c, uint32_t i)
{
    c->nodes[i].next = c->free_head;
    c->free_head = i;
}

/* ---- cache operations ---- */

static void cache_remove(Cache *c, size_t slot)
{
    uint32_t i = c->slots[slot];
    index_remove_slot(c, slot);
    list_unlink(c, i);
    node_release(c, i);
    c->size--;
}

static void cache_set(Cache *c, const char *key, uint32_t klen, const char *val, uint32_t vlen)
{
    uint64_t h = hash_bytes(key, klen);
    size_t s = index_find(c, key, klen, h);
    uint32_t i = c->slots[s];
    if (i != NIL) {
        c->nodes[i].val = val;
        c->nodes[i].vlen = vlen;
        list_touch(c, i);
        return;
    }

    i = node_alloc(c);
    c->nodes[i] = (Node){ .key = key, .val = val, .hash = h, .klen = klen, .vlen = vlen };
    c->slots[s] = i;
    list_push_front(c, i);
    c->size++;

    if (c->size > c->capacity) {
        const Node *lru = &c->nodes[c->tail];
        cache_remove(c, index_find(c, lru->key, lru->klen, lru->hash));
    }
    /* Keep the load factor at or below 1/2. */
    if ((size_t)c->size * 2 > c->mask + 1)
        index_grow(c);
}

static const Node *cache_get(Cache *c, const char *key, uint32_t klen)
{
    uint32_t i = c->slots[index_find(c, key, klen, hash_bytes(key, klen))];
    if (i == NIL)
        return NULL;
    list_touch(c, i);
    return &c->nodes[i];
}

static bool cache_del(Cache *c, const char *key, uint32_t klen)
{
    size_t s = index_find(c, key, klen, hash_bytes(key, klen));
    if (c->slots[s] == NIL)
        return false;
    cache_remove(c, s);
    return true;
}

/* ---- input parsing ---- */

typedef struct {
    const char *p;
    uint32_t len;
} Token;

/* Split line [p, end) on spaces into at most max tokens; returns the count,
 * or max + 1 if there are more. */
static size_t tokenize(const char *p, const char *end, Token *toks, size_t max)
{
    size_t n = 0;
    while (p < end) {
        if (*p == ' ') {
            p++;
            continue;
        }
        const char *start = p;
        while (p < end && *p != ' ')
            p++;
        if (n == max)
            return max + 1;
        toks[n++] = (Token){ start, (uint32_t)(p - start) };
    }
    return n;
}

static bool token_is(Token t, const char *word)
{
    size_t n = strlen(word);
    return t.len == n && memcmp(t.p, word, n) == 0;
}

/* Find the end of the line starting at p (excluding '\n' and a trailing '\r'),
 * and set *next to the start of the following line. */
static const char *line_end(const char *p, const char *end, const char **next)
{
    const char *nl = memchr(p, '\n', (size_t)(end - p));
    const char *e = nl ? nl : end;
    *next = nl ? nl + 1 : end;
    if (e > p && e[-1] == '\r')
        e--;
    return e;
}

static uint32_t parse_capacity(const char *p, const char *end)
{
    while (p < end && (*p == ' ' || *p == '\t'))
        p++;
    uint64_t v = 0;
    while (p < end && *p >= '0' && *p <= '9' && v <= UINT32_MAX)
        v = v * 10 + (uint64_t)(*p++ - '0');
    if (v < 1)
        v = 1;
    return v > UINT32_MAX - 1 ? UINT32_MAX - 1 : (uint32_t)v;
}

int cmd_lru(void)
{
    Input in = input_read_all(stdin);
    const char *p = in.data;
    const char *end = in.data + in.len;
    Output out;
    out_init(&out, stdout);

    if (p < end) {
        const char *next;
        const char *e = line_end(p, end, &next);
        Cache cache;
        cache_init(&cache, parse_capacity(p, e));
        p = next;

        while (p < end) {
            e = line_end(p, end, &next);
            Token t[3];
            size_t n = tokenize(p, e, t, 3);
            p = next;

            if (n == 3 && token_is(t[0], "SET")) {
                cache_set(&cache, t[1].p, t[1].len, t[2].p, t[2].len);
            } else if (n == 2 && token_is(t[0], "GET")) {
                const Node *node = cache_get(&cache, t[1].p, t[1].len);
                if (node)
                    out_write(&out, node->val, node->vlen);
                else
                    out_write(&out, "NULL", 4);
                out_char(&out, '\n');
            } else if (n == 2 && token_is(t[0], "DEL")) {
                out_char(&out, cache_del(&cache, t[1].p, t[1].len) ? '1' : '0');
                out_char(&out, '\n');
            } else if (n == 1 && token_is(t[0], "SIZE")) {
                out_u64(&out, cache.size);
                out_char(&out, '\n');
            }
            /* Anything else is not a valid command and is ignored. */
        }
        cache_free(&cache);
    }

    out_finish(&out);
    input_free(&in);
    return EXIT_SUCCESS;
}

#include "commands.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static const struct {
    const char *name;
    int (*run)(void);
} commands[] = {
    { "wordfreq", cmd_wordfreq },
    { "lru", cmd_lru },
    { "calc", cmd_calc },
};

int main(int argc, char **argv)
{
    if (argc >= 2) {
        for (size_t i = 0; i < sizeof commands / sizeof commands[0]; i++) {
            if (strcmp(argv[1], commands[i].name) == 0)
                return commands[i].run();
        }
    }
    fprintf(stderr, "usage: %s wordfreq|lru|calc < input\n", argc ? argv[0] : "app");
    return EXIT_FAILURE;
}

/* wordfreq: print the 10 most frequent ASCII-letter words of stdin. */
#include "commands.h"
#include "hash.h"
#include "io.h"

#include <stdbool.h>
#include <stdlib.h>
#include <string.h>

enum { TOP_N = 10 };

/* Words point into the (lowercased in place) input buffer; no copies. */
typedef struct {
    const char *word; /* NULL marks an empty slot */
    size_t len;
    uint64_t hash;
    uint64_t count;
} Entry;

typedef struct {
    Entry *slots;
    size_t cap; /* power of two */
    size_t used;
} Table;

static void table_init(Table *t, size_t cap)
{
    t->slots = xcalloc(cap, sizeof *t->slots);
    t->cap = cap;
    t->used = 0;
}

static void table_grow(Table *t)
{
    Table bigger;
    table_init(&bigger, t->cap * 2);
    size_t mask = bigger.cap - 1;
    for (size_t i = 0; i < t->cap; i++) {
        const Entry *e = &t->slots[i];
        if (!e->word)
            continue;
        size_t j = e->hash & mask;
        while (bigger.slots[j].word)
            j = (j + 1) & mask;
        bigger.slots[j] = *e;
    }
    bigger.used = t->used;
    free(t->slots);
    *t = bigger;
}

static void table_add(Table *t, const char *word, size_t len)
{
    uint64_t h = hash_bytes(word, len);
    size_t mask = t->cap - 1;
    size_t i = h & mask;
    for (;;) {
        Entry *e = &t->slots[i];
        if (!e->word)
            break;
        if (e->hash == h && e->len == len && memcmp(e->word, word, len) == 0) {
            e->count++;
            return;
        }
        i = (i + 1) & mask;
    }
    t->slots[i] = (Entry){ .word = word, .len = len, .hash = h, .count = 1 };
    if (++t->used * 4 > t->cap * 3)
        table_grow(t);
}

/* Byte-order comparison of two words; a proper prefix sorts first. */
static int word_cmp(const Entry *a, const Entry *b)
{
    size_t n = a->len < b->len ? a->len : b->len;
    int c = memcmp(a->word, b->word, n);
    if (c)
        return c;
    return (a->len > b->len) - (a->len < b->len);
}

/* True if a should be listed before b. */
static bool ranks_before(const Entry *a, const Entry *b)
{
    if (a->count != b->count)
        return a->count > b->count;
    return word_cmp(a, b) < 0;
}

static inline bool is_alpha(unsigned char c)
{
    return (unsigned char)((c | 0x20) - 'a') < 26;
}

int cmd_wordfreq(void)
{
    Input in = input_read_all(stdin);
    Table table;
    table_init(&table, 1 << 12);

    unsigned char *p = (unsigned char *)in.data;
    unsigned char *end = p + in.len;
    while (p < end) {
        if (!is_alpha(*p)) {
            p++;
            continue;
        }
        unsigned char *start = p;
        do {
            *p |= 0x20; /* ASCII lowercase */
            p++;
        } while (p < end && is_alpha(*p));
        table_add(&table, (const char *)start, (size_t)(p - start));
    }

    /* Partial selection: keep the best TOP_N entries in sorted order. */
    const Entry *top[TOP_N];
    size_t ntop = 0;
    for (size_t i = 0; i < table.cap; i++) {
        const Entry *e = &table.slots[i];
        if (!e->word)
            continue;
        if (ntop == TOP_N && !ranks_before(e, top[TOP_N - 1]))
            continue;
        size_t j = ntop < TOP_N ? ntop++ : TOP_N - 1;
        while (j > 0 && ranks_before(e, top[j - 1])) {
            top[j] = top[j - 1];
            j--;
        }
        top[j] = e;
    }

    Output out;
    out_init(&out, stdout);
    for (size_t i = 0; i < ntop; i++) {
        out_u64(&out, top[i]->count);
        out_char(&out, ' ');
        out_write(&out, top[i]->word, top[i]->len);
        out_char(&out, '\n');
    }
    out_finish(&out);

    free(table.slots);
    input_free(&in);
    return EXIT_SUCCESS;
}
